# are spread over the GPUs (one process per GPU) with output/<name>/run.log each.
RUNS = "__ABR_RUNS__"
CMD = RUNS[0]["cmd"] if len(RUNS) == 1 else None
EXPECTED_COMMIT = "__ABR_COMMIT__"
KERNEL_URL = "__ABR_KERNEL_URL__"
