# ---------------------------------------------------------------------------------
# 1. Code snapshot
# ---------------------------------------------------------------------------------
def locate_and_copy_code():
    if os.path.exists(REPO):
        shutil.rmtree(REPO)
    archives = sorted(glob.glob(os.path.join(INPUT, "**", "abr-code.tar.gz"), recursive=True))
    archives = [a for a in archives if os.path.isfile(a)]
    if archives:
        log(f"extracting {archives[0]}")
        tmp = os.path.join(WORK, "_code_extract")
        shutil.rmtree(tmp, ignore_errors=True)
        with tarfile.open(archives[0]) as t:
            try:
                t.extractall(tmp, filter="data")
            except TypeError:  # python < 3.10.12
                t.extractall(tmp)
        shutil.move(os.path.join(tmp, "repo"), REPO)
        shutil.rmtree(tmp, ignore_errors=True)
        ENV["code_source"] = archives[0]
    else:
        # Kaggle may auto-extract archives: look for an extracted COMMIT file.
        commits = sorted(glob.glob(os.path.join(INPUT, "**", "repo", "COMMIT"), recursive=True))
        if not commits:
            listing = sh(f"find {INPUT} -maxdepth 4 | head -100")[1]
            raise RuntimeError(f"code snapshot not found under {INPUT}:\n{listing}")
        src = os.path.dirname(commits[0])
        log(f"copying extracted snapshot {src}")
        shutil.copytree(src, REPO)
        ENV["code_source"] = src
    commit = open(os.path.join(REPO, "COMMIT")).read().strip()
    ENV["commit"] = commit
    if commit != EXPECTED_COMMIT:
        raise RuntimeError(f"code snapshot commit {commit} != expected {EXPECTED_COMMIT}; "
                           "the dataset version attached to this kernel is not the one launched")
    snap = os.path.join(REPO, "git_snapshot.json")
    ENV["git_snapshot_present"] = os.path.exists(snap)
    if ENV["git_snapshot_present"]:
        import hashlib
        ENV["git_snapshot_sha256"] = hashlib.sha256(open(snap, "rb").read()).hexdigest()
    log(f"code snapshot at {REPO}, commit {commit}, git_snapshot.json present: "
        f"{ENV['git_snapshot_present']}")


def setup_token_cache():
    """Locate the mounted token-cache dataset, hash every cache file, verify the hashes.

    Returns the directory to export as ABR_CACHE_DIR (or None)."""
    if not TOKEN_CACHE:
        return None
    import hashlib
    files = sorted(f for f in glob.glob(os.path.join(INPUT, "**", "wikitext103_*_gpt2.pt"),
                                        recursive=True) if os.path.isfile(f))
    slug = TOKEN_CACHE["ref"].split("/")[-1]
    files = [f for f in files if slug in f] or files
    info = {"ref": TOKEN_CACHE["ref"], "expected_sha256": TOKEN_CACHE.get("expected_sha256") or {},
            "files": {}}
    ENV["token_cache"] = info
    if not files:
        raise RuntimeError(f"token cache dataset {TOKEN_CACHE['ref']} not found under {INPUT}")
    dirs = {os.path.dirname(f) for f in files}
    if len(dirs) != 1:
        raise RuntimeError(f"token cache files are in several directories: {sorted(dirs)}")
    for f in files:
        h = hashlib.sha256()
        with open(f, "rb") as fh:
            for chunk in iter(lambda: fh.read(1 << 20), b""):
                h.update(chunk)
        info["files"][os.path.basename(f)] = {"sha256": h.hexdigest(), "bytes": os.path.getsize(f)}
    bad = {k: (v, info["files"].get(k, {}).get("sha256")) for k, v in info["expected_sha256"].items()
           if info["files"].get(k, {}).get("sha256") != v}
    info["verified"] = not bad and bool(info["expected_sha256"])
    if bad:
        raise RuntimeError(f"token cache SHA-256 mismatch (expected, found): {bad}")
    info["dir"] = dirs.pop()
    log(f"token cache {TOKEN_CACHE['ref']} at {info['dir']}: {sorted(info['files'])} "
        f"(verified={info['verified']})")
    return info["dir"]


