def gpu_info():
    rc, out = sh("nvidia-smi --query-gpu=name,driver_version,memory.total,compute_cap "
                 "--format=csv,noheader")
    if rc != 0 or not out.strip():
        ENV["no_gpu"] = True
        log("NO GPU visible (nvidia-smi failed). If the kernel was pushed with enable_gpu, "
            "Kaggle may have refused the accelerator: the owner must phone-verify the account "
            "at https://www.kaggle.com/settings.")
        return
    fields = [f.strip() for f in out.strip().splitlines()[0].split(",")]
    ENV["gpu_count"] = len(out.strip().splitlines())
    ENV["gpu_name"], ENV["driver_version"] = fields[0], fields[1]
    ENV["gpu_memory_total"] = fields[2] if len(fields) > 2 else None
    ENV["gpu_compute_cap"] = fields[3] if len(fields) > 3 else None
    rc, smi = sh("nvidia-smi")
    m = re.search(r"CUDA Version:\s*([\d.]+)", smi)
    ENV["driver_cuda_version"] = m.group(1) if m else None


def torch_info():
    import torch
    ENV["torch"] = torch.__version__
    ENV["torch_cuda"] = torch.version.cuda
    ENV["cudnn"] = torch.backends.cudnn.version() if torch.backends.cudnn.is_available() else None
    ENV["cxx11abi"] = bool(torch._C._GLIBCXX_USE_CXX11_ABI)
    ENV["cuda_available"] = torch.cuda.is_available()
    if torch.cuda.is_available():
        ENV["torch_gpu_name"] = torch.cuda.get_device_name(0)
        ENV["torch_compute_capability"] = list(torch.cuda.get_device_capability(0))
        ENV["torch_arch_list"] = torch.cuda.get_arch_list()
    ENV["torch_device_count"] = torch.cuda.device_count() if torch.cuda.is_available() else 0
    return torch


# ---------------------------------------------------------------------------------
# 3. mamba-ssm / causal-conv1d install
# ---------------------------------------------------------------------------------
_WHEEL_RE = re.compile(r"\+cu(\d+)torch(\d+\.\d+)cxx11abi(TRUE|FALSE)-(cp\d+)-(cp\d+)-linux_x86_64\.whl$")


def find_wheel(repo, cuda_major, torch_mm, abi, cp):
    """Newest GitHub release asset matching cu<major>*, torch major.minor, ABI and python."""
    url = f"https://api.github.com/repos/{repo}/releases?per_page=40"
    req = urllib.request.Request(url, headers={"Accept": "application/vnd.github+json",
                                               "User-Agent": "abr-kaggle-runner"})
    with urllib.request.urlopen(req, timeout=60) as r:
        releases = json.load(r)
    for rel in releases:  # newest first
        if rel.get("draft") or rel.get("prerelease"):
            continue
        best = None
        for asset in rel.get("assets", []):
            m = _WHEEL_RE.search(asset["name"])
            if not m:
                continue
            cu, tv, ab, py, _ = m.groups()
            if cu.startswith(str(cuda_major)) and tv == torch_mm and ab == abi and py == cp:
                # prefer the highest cuda minor <= runtime (cu12 > cu122 naming both ok)
                if best is None or cu > best[0]:
                    best = (cu, asset["browser_download_url"], rel["tag_name"])
        if best:
            return {"url": best[1], "tag": best[2], "asset_cuda": best[0]}
    return None


# Versions validated by the compatibility check (results/kaggle/compat_check).
PINNED = {"causal_conv1d": ("causal-conv1d", "1.7.0", "CAUSAL_CONV1D"),
          "mamba_ssm": ("mamba-ssm", "2.3.2.post1", "MAMBA")}
WHEEL_DIR = os.path.join(OUT, "wheels")


def local_tag(torch):
    """e.g. cu130torch2.11sm75: CUDA, torch major.minor and the GPU arch the wheel targets."""
    cuda = (torch.version.cuda or "0").replace(".", "")
    tmm = ".".join(torch.__version__.split("+")[0].split(".")[:2])
    cap = torch.cuda.get_device_capability(0) if torch.cuda.is_available() else (0, 0)
    return f"cu{cuda}torch{tmm}sm{cap[0]}{cap[1]}", f"{cap[0]}{cap[1]}"


def mounted_wheels(tag, cp):
    """Wheels built earlier by this runner and uploaded as a private dataset.

    Kaggle strips the '+' from uploaded file names (mamba_ssm-2.3.2.post1cu130torch2.11sm75-...),
    which pip rejects, so matching files are copied to a local dir under their real name."""
    found = {}
    dst = os.path.join(WORK, "_mounted_wheels")
    for pkg, (_, ver, _) in PINNED.items():
        hits = []
        for w in glob.glob(os.path.join(INPUT, "**", f"{pkg}-*.whl"), recursive=True):
            b = os.path.basename(w)
            for sep in ("+", ""):
                if b == f"{pkg}-{ver}{sep}{tag}-{cp}-{cp}-linux_x86_64.whl":
                    hits.append(w)
        if hits:
            os.makedirs(dst, exist_ok=True)
            fixed = os.path.join(dst, f"{pkg}-{ver}+{tag}-{cp}-{cp}-linux_x86_64.whl")
            shutil.copy(sorted(hits)[-1], fixed)
            found[pkg] = fixed
    return found


def patch_setup_for_arch(setup_py, arch):
    """Compile only for this GPU's arch (the stock setup.py builds 9 archs: ~75 min on Kaggle)."""
    src = open(setup_py).read()
    pat = re.compile(r'cc_flag\.append\("-gencode"\)\n(\s*)cc_flag\.append\("arch=compute_(\d+),code=sm_\d+"\)')
    archs = [m.group(2) for m in pat.finditer(src)]
    if arch not in archs:
        raise RuntimeError(f"arch sm_{arch} not in setup.py arch list {archs}")
    out = pat.sub(lambda m: m.group(0) if m.group(2) == arch else f"pass\n{m.group(1)}pass", src)
    open(setup_py, "w").write(out)
    return archs


def pypi_sdist(name, version):
    with urllib.request.urlopen(f"https://pypi.org/pypi/{name}/{version}/json", timeout=60) as r:
        meta = json.load(r)
    return [u["url"] for u in meta["urls"] if u["packagetype"] == "sdist"][0]


def build_wheels(torch, tag, arch):
    os.makedirs(WHEEL_DIR, exist_ok=True)
    bdir = os.path.join(WORK, "_build")
    os.makedirs(bdir, exist_ok=True)
    built = {}
    for pkg, (name, ver, envp) in PINNED.items():  # causal_conv1d first
        url = pypi_sdist(name, ver)
        tgz = os.path.join(bdir, os.path.basename(url))
        urllib.request.urlretrieve(url, tgz)
        with tarfile.open(tgz) as t:
            t.extractall(bdir)
        src = os.path.join(bdir, os.path.basename(url)[:-len(".tar.gz")])
        patch_setup_for_arch(os.path.join(src, "setup.py"), arch)
        env = dict(os.environ, MAX_JOBS="4", **{f"{envp}_FORCE_BUILD": "TRUE",
                                                 f"{envp}_LOCAL_VERSION": tag})
        rc, _ = sh(f"pip wheel --no-build-isolation --no-deps -w {WHEEL_DIR} {src}", env=env)
        whl = sorted(glob.glob(os.path.join(WHEEL_DIR, f"{pkg}-*+{tag}-*.whl")))
        if rc != 0 or not whl:
            raise RuntimeError(f"building {name} {ver} for sm_{arch} failed")
        built[pkg] = whl[-1]
        # install right away: mamba-ssm's build imports causal_conv1d's presence lazily
        sh(f"pip install {whl[-1]}", check=True)
    shutil.rmtree(bdir, ignore_errors=True)
    return built


def install_mamba(torch):
    t0 = time.time()
    info = {}
    torch_mm = ".".join(torch.__version__.split("+")[0].split(".")[:2])
    cuda_major = (torch.version.cuda or "12").split(".")[0]
    abi = "TRUE" if torch._C._GLIBCXX_USE_CXX11_ABI else "FALSE"
    cp = f"cp{sys.version_info.major}{sys.version_info.minor}"
    tag, arch = local_tag(torch)
    info["match_key"] = {"torch": torch_mm, "cuda_major": cuda_major, "cxx11abi": abi,
                         "python": cp, "local_tag": tag}
    sh("pip install einops ninja packaging")
    # 1. wheels from a mounted private dataset (built by an earlier session of this runner)
    mw = mounted_wheels(tag, cp)
    info["mounted_wheels"] = mw
    if mw:
        import hashlib
        info["mounted_wheels_sha256"] = {
            k: hashlib.sha256(open(v, "rb").read()).hexdigest() for k, v in mw.items()}
    if len(mw) == len(PINNED):
        rc, _ = sh(f"pip install {mw['causal_conv1d']} {mw['mamba_ssm']}")
        if rc == 0:
            info["method"] = "mounted_wheels"
            info["install_seconds"] = round(time.time() - t0, 1)
            return info
    # 2. official GitHub release wheels matching torch/CUDA/python/ABI
    wheels = {}
    for pkg, repo in (("causal_conv1d", "Dao-AILab/causal-conv1d"), ("mamba_ssm", "state-spaces/mamba")):
        try:
            wheels[pkg] = find_wheel(repo, cuda_major, torch_mm, abi, cp)
        except Exception as e:
            log(f"wheel lookup for {pkg} failed: {e}")
            wheels[pkg] = None
    info["wheels"] = wheels
    if all(wheels.values()):
        rc, _ = sh(f"pip install {wheels['causal_conv1d']['url']} {wheels['mamba_ssm']['url']}")
        if rc == 0:
            info["method"] = "prebuilt_wheels"
            info["install_seconds"] = round(time.time() - t0, 1)
            return info
    # 3. build pinned versions from source for this GPU arch only; wheels kept in output/wheels
    try:
        info["built_wheels"] = build_wheels(torch, tag, arch)
        info["method"] = f"built_from_source_sm{arch}"
    except Exception:
        info["build_error"] = traceback.format_exc()
        log(info["build_error"])
        # 4. stock build (all archs, slow)
        info["method"] = "pip_no_build_isolation"
        for pkg, (name, ver, _) in PINNED.items():
            sh(f"pip install --no-build-isolation {name}=={ver}", env=dict(os.environ, MAX_JOBS="4"))
    info["install_seconds"] = round(time.time() - t0, 1)
    return info


# ---------------------------------------------------------------------------------
# Triton kernel cache (Mamba-2 kernels take minutes to JIT-compile on a T4)
# ---------------------------------------------------------------------------------
# Outside /kaggle/working, so its thousands of small files are not kernel outputs
# (they made `kaggle kernels output` take > 1 h); only the tarball is saved.
TRITON_CACHE = os.environ.get("ABR_TRITON_CACHE", "/tmp/abr_triton_cache")


def restore_triton_cache():
    os.makedirs(TRITON_CACHE, exist_ok=True)
    for tgz in sorted(glob.glob(os.path.join(INPUT, "**", "triton_cache.tar.gz"), recursive=True)):
        try:
            with tarfile.open(tgz) as t:
                t.extractall(os.path.dirname(TRITON_CACHE) or "/tmp")
                src = os.path.join(os.path.dirname(TRITON_CACHE) or "/tmp", "triton_cache")
                if os.path.isdir(src) and src != TRITON_CACHE:
                    shutil.copytree(src, TRITON_CACHE, dirs_exist_ok=True)
                    shutil.rmtree(src, ignore_errors=True)
            log(f"restored Triton cache from {tgz}")
            return tgz
        except Exception as e:
            log(f"could not restore Triton cache {tgz}: {e}")
    # Kaggle may have auto-extracted the archive into a directory
    for d in sorted(glob.glob(os.path.join(INPUT, "**", "triton_cache"), recursive=True)):
        inner = os.path.join(d, "triton_cache")   # tarball extracted by Kaggle: triton_cache/triton_cache/
        if os.path.isdir(inner):
            d = inner
        if os.path.isdir(d) and d != TRITON_CACHE:
            shutil.copytree(d, TRITON_CACHE, dirs_exist_ok=True)
            log(f"restored Triton cache from {d}")
            return d
    return None


def save_triton_cache():
    if os.path.isdir(TRITON_CACHE) and os.listdir(TRITON_CACHE):
        with tarfile.open(os.path.join(OUT, "triton_cache.tar.gz"), "w:gz") as t:
            t.add(TRITON_CACHE, arcname="triton_cache")


def installed_versions():
    code = ("import json,importlib.metadata as m\n"
            "out={}\n"
            "for p in ['torch','triton','mamba-ssm','causal-conv1d','transformers','datasets','wandb','einops','numpy']:\n"
            "    try: out[p]=m.version(p)\n"
            "    except Exception as e: out[p]=None\n"
            "for mod in ['mamba_ssm','causal_conv1d']:\n"
            "    try:\n"
            "        x=__import__(mod); out[mod+'_import']='ok '+getattr(x,'__version__','?')\n"
            "    except Exception as e: out[mod+'_import']='FAILED: '+repr(e)[:400]\n"
            "print('VERSIONS_JSON='+json.dumps(out))\n")
    path = os.path.join(WORK, "_versions.py")
    with open(path, "w") as f:
        f.write(code)
    rc, out = sh(f"{sys.executable} {path}")
    os.remove(path)
    for line in out.splitlines():
        if line.startswith("VERSIONS_JSON="):
            return json.loads(line[len("VERSIONS_JSON="):])
    return {"error": out[-2000:]}


# ---------------------------------------------------------------------------------
# Named runs: one process per GPU, resumable across sessions
# ---------------------------------------------------------------------------------
def find_previous_run_dir(run_name):
    """Previous session's output/<run>/ from the attached kernel outputs (newest session wins)."""
    best = None
    for src in RESUME_SOURCES:
        slug = src.split("/")[-1]
        for st in glob.glob(os.path.join(INPUT, "**", run_name, "run_status.json"), recursive=True):
            if slug not in st:
                continue
            try:
                n = int(json.load(open(st)).get("sessions", 0))
            except Exception:
                n = 0
            if best is None or n > best[0]:
                best = (n, os.path.dirname(st))
    return best[1] if best else None


def write_status(path, st):
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(st, f, indent=2, sort_keys=True)
    os.replace(tmp, path)


def run_named(run, gpu_slot, base_env):
    name = run["name"]
    rdir = os.path.join(OUT, name)
    remaining = T_START + SESSION_BUDGET_S - time.time()
    if remaining < MIN_RUN_S:
        # Not started: no output dir, so the queue keeps it pending with its old resume source.
        log(f"[{name}] skipped: only {remaining / 60:.0f} min of the session budget left")
        ENV.setdefault("skipped_runs", []).append(name)
        return name, None
    max_hours = remaining / 3600.0
    prev = find_previous_run_dir(name)
    prev_status = {}
    if prev:
        log(f"[{name}] restoring previous session output from {prev}")
        shutil.copytree(prev, rdir, dirs_exist_ok=True)
        try:
            prev_status = json.load(open(os.path.join(rdir, "run_status.json")))
        except Exception:
            prev_status = {}
        old_log = os.path.join(rdir, "run.log")
        if os.path.exists(old_log):
            keep = os.path.join(rdir, "previous_sessions")
            os.makedirs(keep, exist_ok=True)
            shutil.move(old_log, os.path.join(keep, f"run.session{prev_status.get('sessions', 0)}.log"))
    os.makedirs(rdir, exist_ok=True)
    status_path = os.path.join(rdir, "run_status.json")
    sessions = int(prev_status.get("sessions", 0)) + 1
    cmd = run["cmd"].replace("{max_hours}", f"{max_hours:.3f}")
    st = {"name": name, "cmd": cmd, "max_hours": round(max_hours, 3), "lane": run.get("lane"),
          "commit": ENV.get("commit"), "kernel_ref": KERNEL_REF,
          "kernel_url": KERNEL_URL, "dataset_version": DATASET_VERSION, "sessions": sessions,
          "gpu_slot": gpu_slot, "resumed_from": prev, "state": "running", "exit_code": None,
          "started_utc": utcnow(),
          "history": list(prev_status.get("history", []))}
    write_status(status_path, st)
    env = dict(base_env)
    env.update({"ABR_OUTPUT_DIR": rdir, "ABR_RUN_NAME": name, "ABR_RESUME_DIR": rdir,
                "ABR_RESUMED": "1" if prev else "0", "ABR_SESSION_INDEX": str(sessions),
                "WANDB_DIR": os.path.join(rdir, "wandb"),
                "ABR_SESSION_DEADLINE": str(int(T_START + SESSION_BUDGET_S)),
                "ABR_MAX_HOURS": f"{max_hours:.3f}"})
    if gpu_slot is not None:
        env["CUDA_VISIBLE_DEVICES"] = str(gpu_slot)
    os.makedirs(env["WANDB_DIR"], exist_ok=True)
    procs = {}
    stopped = threading.Event()

    def watchdog():
        remaining = T_START + SESSION_BUDGET_S - time.time()
        if remaining > 0 and not stopped.wait(remaining):
            p = procs.get("p")
            if p and p.poll() is None:
                log(f"[{name}] session budget reached, sending SIGTERM (resume next session)")
                st["stopped_by_deadline"] = True
                try:
                    os.killpg(p.pid, signal.SIGTERM)
                except Exception:
                    pass
    threading.Thread(target=watchdog, daemon=True).start()
    with open(os.path.join(rdir, "run.log"), "a", buffering=1) as lf:
        rc, _ = sh(cmd, cwd=REPO, env=env, logfile=lf, prefix=f"[{name}] ",
                   on_start=lambda p: procs.__setitem__("p", p))
    stopped.set()
    st["exit_code"] = rc
    st["finished_utc"] = utcnow()
    st["state"] = "done" if rc == 0 else ("preempted" if st.get("stopped_by_deadline") else "failed")
    st["history"].append({"session": sessions, "kernel_ref": KERNEL_REF, "exit_code": rc,
                          "started_utc": st["started_utc"], "finished_utc": st["finished_utc"],
                          "state": st["state"]})
    write_status(status_path, st)
    return name, rc


def run_all_named(base_env, n_gpus):
    slots = list(range(n_gpus)) if n_gpus > 0 else [None]
    queues = {i: [] for i in range(len(slots))}
    for k, run in enumerate(RUNS):
        lane = run.get("lane")
        queues[(k if lane is None else int(lane)) % len(slots)].append(run)
    results = {}

    def worker(i):
        for run in queues[i]:
            try:
                n, rc = run_named(run, slots[i], base_env)
            except Exception:
                log(f"[{run['name']}] runner error:\n{traceback.format_exc()}")
                n, rc = run["name"], 1
            results[n] = rc
    threads = [threading.Thread(target=worker, args=(i,)) for i in queues if queues[i]]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    return results


# ---------------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------------
def main():
    rc = 1
    save_env()
    try:
        locate_and_copy_code()
        cache_dir = setup_token_cache()
        save_env()
        gpu_info()
        torch = torch_info()
        save_env()
        try:
            if SKIP_INSTALL:
                raise RuntimeError("ABR_RUNNER_SKIP_INSTALL=1 (local runner test)")
            ENV["mamba_install"] = install_mamba(torch)
        except Exception:
            ENV["mamba_install"] = {"error": traceback.format_exc()}
            log(ENV["mamba_install"]["error"])
        if not SKIP_INSTALL:
            sh('pip install "datasets" "transformers<5" "wandb"')
        ENV["versions"] = installed_versions()
        ENV["mamba_ssm"] = ENV["versions"].get("mamba-ssm")
        ENV["causal_conv1d"] = ENV["versions"].get("causal-conv1d")
        sh(f"{sys.executable} -m pip freeze > " + os.path.join(OUT, "pip_freeze.txt"))
        save_env()

        env = dict(os.environ)
        env.update({
            "WANDB_MODE": "offline",
            "WANDB_DIR": os.path.join(OUT, "wandb"),
            "KAGGLE_KERNEL_URL": KERNEL_URL,
            "KAGGLE_DATASET_VERSION": str(DATASET_VERSION),
            "CODE_COMMIT": ENV["commit"],
            "ABR_OUTPUT_DIR": OUT,
            "ABR_RESUME_DIRS": ":".join(os.path.join(INPUT, s.split("/")[-1]) for s in RESUME_SOURCES),
            "PYTHONUNBUFFERED": "1",
        })
        if cache_dir:
            env["ABR_CACHE_DIR"] = cache_dir
        ENV["triton_cache_restored_from"] = restore_triton_cache()
        env["TRITON_CACHE_DIR"] = TRITON_CACHE
        # Kaggle does not tell a running kernel its own version number; the launcher
        # records the real one in results/kaggle/<name>/launch.json. Pass one through
        # only if the platform provides it.
        kv = os.environ.get("KAGGLE_KERNEL_VERSION") or os.environ.get("KAGGLE_KERNEL_VERSION_NUMBER")
        if kv:
            env["KAGGLE_KERNEL_VERSION"] = kv
        ENV["kaggle_kernel_version_env"] = kv
        os.makedirs(env["WANDB_DIR"], exist_ok=True)
        ENV["cmd_started_utc"] = utcnow()
        save_env()
        if len(RUNS) == 1 and not RUNS[0].get("name"):
            log(f"running command in {REPO}: {CMD}")
            rc, _ = sh(CMD, cwd=REPO, env=env)
            ENV["cmd_exit_code"] = rc
        else:
            n_gpus = int(ENV.get("torch_device_count") or 0)
            log(f"running {len(RUNS)} named runs on {n_gpus} GPU(s)")
            res = run_all_named(env, n_gpus)
            ENV["run_exit_codes"] = res
            rc = 0 if all(v in (0, None) for v in res.values()) else 1
    except Exception:
        ENV["runner_error"] = traceback.format_exc()
        log(ENV["runner_error"])
        rc = 1
    finally:
        try:
            save_triton_cache()
        except Exception as e:
            log(f"could not save Triton cache: {e}")
        ENV["finished_utc"] = utcnow()
        save_env()
        # The exact code is preserved in the dataset version; don't duplicate it in outputs.
        shutil.rmtree(REPO, ignore_errors=True)
        log(f"done, exit code {rc}")
        _log.close()
    sys.exit(rc)


if __name__ == "__main__":
    main()
